mapper.select:
select orders.*, upcoming_movies.name as goodsName, user.name as userName from orders left join upcoming_movies on orders.goods_id = upcoming_movies.id left join user on orders.user_id = user.id
orders.user_id = #{userId}
order by orders.id desc

mapper.update:
update orders set order_no=#{orderNo}, goods_id=#{goodsId}, num=#{num}, user_id=#{userId}, 
status=#{status}, time=#{time}, total_price=#{totalPrice}, screening_id=#{screeningId}, 
seat_info=#{seatInfo}, hall_name=#{hallName}, show_time=#{showTime}
where id = #{id}
